class DelegationExample {
    int value;

public:
    // Target constructor
    DelegationExample(int v) : value(v) {}

    // Delegating constructor
    DelegationExample() : DelegationExample(42) {}

    // Delegating constructor (multiple arguments)
    DelegationExample(int a, int b) : DelegationExample(a + b) {}

    // Cannot delegate and initialize members:
    // DelegationExample(double d) : DelegationExample(0), value(d) {} // ERROR
};

// Note: Delegation must occur in the member initializer list.
